const src = $('Route destination').item.json;
const statusCode = Number($json.statusCode || 0);
const ok = statusCode >= 200 && statusCode < 300;
return [{
  json: {
    ...src,
    delivery_ok: ok,
    provider_status_code: statusCode,
    provider_body: typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body ?? {}),
    provider_record_id: $json.body?.records?.[0]?.id || $json.body?.logId || null
  }
}];
